custom_fields.main:
[[[
const now = new Date();

const timeParts = now
  .toLocaleTimeString([], {
    hour: 'numeric',
    minute: '2-digit'
  })
  .match(/^(.+?)\s?(AM|PM)?$/i);

const mainTime = timeParts?.[1] || '';
const meridiem = timeParts?.[2] || '';

const date = now.toLocaleDateString([], {
  weekday: 'short',
  month: 'short',
  day: 'numeric'
});

return `
  <div style="
    width:100%;
    height:100%;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    box-sizing:border-box;
  ">
    <div style="
      display:flex;
      align-items:baseline;
      justify-content:center;
      width:100%;
      white-space:nowrap;
    ">
      <span style="
        font-size:40px;
        font-weight:500;
        line-height:1;
        letter-spacing:-0.6px;
        color:rgba(255,255,255,0.80);
      ">
        ${mainTime}
      </span>
      <span style="
        margin-left:4px;
        font-size:13px;
        font-weight:400;
        line-height:1;
        color:rgba(220,232,242,0.68);
      ">
        ${meridiem}
      </span>
    </div>
    <div style="
      margin-top:7px;
      width:100%;
      text-align:center;
      font-size:13px;
      line-height:1;
      color:rgba(220,232,242,0.58);
      white-space:nowrap;
    ">
      ${date}
    </div>
  </div>
`;
]]]

