custom_fields.calendar:
[[[
const days = [
  ['SUN', ['input_text.calendar_sun_events', 'input_text.calendar_sun_events_2', 'input_text.calendar_sun_events_3']],
  ['MON', ['input_text.calendar_mon_events', 'input_text.calendar_mon_events_2', 'input_text.calendar_mon_events_3']],
  ['TUE', ['input_text.calendar_tue_events', 'input_text.calendar_tue_events_2', 'input_text.calendar_tue_events_3']],
  ['WED', ['input_text.calendar_wed_events', 'input_text.calendar_wed_events_2', 'input_text.calendar_wed_events_3']],
  ['THU', ['input_text.calendar_thu_events', 'input_text.calendar_thu_events_2', 'input_text.calendar_thu_events_3']],
  ['FRI', ['input_text.calendar_fri_events', 'input_text.calendar_fri_events_2', 'input_text.calendar_fri_events_3']],
  ['SAT', ['input_text.calendar_sat_events', 'input_text.calendar_sat_events_2', 'input_text.calendar_sat_events_3']]
];

const palette = ['blue', 'purple', 'green', 'yellow', 'red'];
const rawDate = states['sensor.date_time']?.state || '';
const dateParts = (rawDate.split(',')[0] || '').split('-').map(Number);
const now = dateParts.length === 3 && dateParts.every(Number.isFinite)
  ? new Date(dateParts[0], dateParts[1] - 1, dateParts[2])
  : new Date();
const weekOffset = Number(states['input_number.calendar_week_offset']?.state || 0);
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - now.getDay() + weekOffset * 7);

const readEvents = helperIds => {
  const value = helperIds.map(helperId => states[helperId]?.state || '').filter(Boolean).join('\n');
  if (!value || value === 'unknown' || value === 'unavailable') return [];
  return value.split('\n').filter(Boolean).map(line => {
    const [name, time] = line.split('||');
    return { name: name || 'Untitled', time: time || 'All day' };
  });
};

const eventCard = (event, color) => `
  <div class="hv-live-event hv-live-${color}">
    <div class="hv-live-event-name">${event.name}</div>
    <div class="hv-live-event-time">${event.time}</div>
  </div>
`;

const dayColumn = (day, helperIds, offset) => {
  const events = readEvents(helperIds);
  const dayPalette = [...palette].sort((a, b) => { const score = value => [...(day + value)].reduce((hash, char) => (hash * 33 + char.charCodeAt(0)) >>> 0, 5381); return score(a) - score(b); });
  const date = new Date(weekStart);
  date.setDate(weekStart.getDate() + offset);
  const isToday = date.getFullYear() === now.getFullYear()
    && date.getMonth() === now.getMonth()
    && date.getDate() === now.getDate();
  const totalEvents = events.length;
  return `
    <div class="hv-live-column${isToday ? ' hv-live-today' : ''}">
      <div class="hv-live-day-header${isToday ? ' hv-live-today-header' : ''}">
        <div class="hv-live-day-name" style="position:relative;text-align:center;">
          <span class="${isToday ? 'hv-live-today-day-label' : ''}">${day}</span>
          <span class="hv-live-date-pill">${date.getMonth() + 1}/${date.getDate()}</span>
        </div>
        <div class="hv-live-day-count${isToday ? ' hv-live-today-count' : ''}"><span>${totalEvents} event${totalEvents === 1 ? '' : 's'}</span> ${isToday ? '<span class="hv-live-today-pill">TODAY</span>' : ''}</div>
      </div>
      <div class="hv-live-event-list${isToday ? ' hv-live-today-event-list' : ' hv-live-day-event-list'}">
        ${events.length ? events.map((event, index) => eventCard(event, dayPalette[index % dayPalette.length])).join('') : '<div class="hv-live-empty">No events</div>'}
      </div>
    </div>
  `;
};

const nextWeekValue = [
  states['input_text.calendar_next_week_events']?.state || '',
  states['input_text.calendar_next_week_events_2']?.state || '',
  states['input_text.calendar_next_week_events_3']?.state || ''
].filter(value => value && value !== 'unknown' && value !== 'unavailable').join('\n');
const nextWeekEvents = nextWeekValue && nextWeekValue !== 'unknown' && nextWeekValue !== 'unavailable'
  ? nextWeekValue.split('\n').filter(Boolean).map(line => {
      const [date, name, time] = line.split('||');
      return { date: date || '', name: name || 'Untitled', time: time || 'All day' };
    })
  : [];
const nextWeekCards = nextWeekEvents.length
  ? nextWeekEvents.map(event => `
      <div style="display:flex;align-items:baseline;gap:7px;padding:8px 0;border-bottom:1px solid #e5eaf0;color:#273449;">
        <span style="flex:0 0 auto;font-size:10px;font-weight:700;white-space:nowrap;">${event.date.split(' ')[0]}</span>
        <span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;font-weight:600;">${event.name}</span>
        <span style="flex:0 0 auto;margin-left:auto;color:#7a8798;font-size:10px;white-space:nowrap;">${event.time}</span>
      </div>
    `).join('')
  : '<div class="hv-live-empty">No appointments</div>';
const nextWeekColumn = `
  <div class="hv-live-column">
    <div class="hv-live-day-header">
      <div class="hv-live-day-name hv-live-overflow-title">NEXT WEEK</div>
      <div class="hv-live-day-count">${nextWeekEvents.length} appointment${nextWeekEvents.length === 1 ? '' : 's'}</div>
    </div>
    <div class="hv-live-event-list hv-live-next-week-list">${nextWeekCards}</div>
  </div>
`;

return `
  <div class="hv-live-week">
    ${days.slice(0, 4).map(([day, helperIds], index) => dayColumn(day, helperIds, index)).join('')}
    ${days.slice(4).map(([day, helperIds], index) => dayColumn(day, helperIds, index + 4)).join('')}
    ${nextWeekColumn}
  </div>
`;

]]]

